import 'dart:typed_data';

/// A model of the outbound *legacy* USB transfer fragmentation observed in
/// NUServer64.sys, SHA-256 67317977...bdfcbd, RVA 0xC5AC.
///
/// This is not a USB command generator or a printing implementation.
/// It simply takes bytes that would already have been generated by the
/// upper-layer Canon USB client and describes their transfer boundaries.
/// Never substitute the beginning of an unrelated IVEC document for the
/// Windows driver's actual command stream.
class NuLegacyFragment {
  const NuLegacyFragment({
    required this.offset,
    required this.totalBytes,
    required this.bytes,
  });

  final int offset;
  final int totalBytes;
  final Uint8List bytes;

  int get count => bytes.length;
  int get remainingAfter => totalBytes - offset - count;
  bool get last => remainingAfter == 0;
}

class NuLegacyFragmenter {
  // Disassembled legacy OUT 0xC5AC / IN 0xC3AC both clamp at 0x400.
  static const int maxFragmentBytes = 0x400;
  static const int legacyHeaderBytes = 0x20;

  /// Model only. No hub/network I/O occurs. The source is the upper-layer
  /// USB client's actual buffer (and its offset), not a guessed print job.
  static Iterable<NuLegacyFragment> splitOut(
    Uint8List transfer, {
    int initialOffset = 0,
  }) sync* {
    if (initialOffset < 0 || initialOffset > transfer.length) {
      throw RangeError.range(initialOffset, 0, transfer.length,
          'initialOffset');
    }
    var offset = initialOffset;
    while (offset < transfer.length) {
      final end = offset + maxFragmentBytes < transfer.length
          ? offset + maxFragmentBytes
          : transfer.length;
      yield NuLegacyFragment(
        offset: offset,
        totalBytes: transfer.length,
        bytes: Uint8List.sublistView(transfer, offset, end),
      );
      offset = end;
    }
  }

  /// In the disassembled legacy driver the OUT allocation is
  /// payload-fragment length + 0x20 for the NU header.
  static int legacyAllocationLength(int fragmentLength) {
    if (fragmentLength < 1 || fragmentLength > maxFragmentBytes) {
      throw RangeError.range(
        fragmentLength, 1, maxFragmentBytes, 'fragmentLength');
    }
    return legacyHeaderBytes + fragmentLength;
  }
}
